SELECT Name, COUNT(*) AS count
FROM MediaType
GROUP BY Name;

SELECT BillingCountry, AVG(Total) AS AverageInvoiceTotal
FROM Invoice
GROUP BY BillingCountry;

SELECT PlaylistId, Name
FROM Playlist
WHERE Quantity > 1000;

SELECT FirstName, LastName, HireDate
FROM Employee
WHERE HireDate = (SELECT MAX(HireDate) FROM Employee);

SELECT income_group, COUNT(*) AS count
FROM countries
GROUP BY income_group;

SELECT AVG(life_expectancy_years) AS population_weighted_average_life_expectancy
FROM country_stats
WHERE iso3 = 'WTO' AND year = 2023;

SELECT iso3, gdp_per_capita_usd, life_expectancy_years
FROM countries
WHERE year = 2023;

SELECT species, COUNT(*) AS count
FROM penguins
GROUP BY species;

SELECT species, AVG(body_mass_g) AS average_body_mass
FROM penguins
GROUP BY species;

SELECT island, year, COUNT(*) AS count_penguins
FROM penguins
GROUP BY island, year;

SELECT AVG(bill_length_mm) AS average_bill_length
FROM penguins
WHERE sex = 'male' OR sex = 'female';

SELECT species, MAX(bill_depth_mm) AS max_bill_depth, MIN(bill_depth_mm) AS min_bill_depth
FROM penguins
GROUP BY species;

SELECT species, (SELECT AVG(body_mass_g) FROM penguins WHERE sex = 'male') - (SELECT AVG(body_mass_g) FROM penguins WHERE sex = 'female') AS gap
FROM penguins
GROUP BY species;

SELECT COUNT(*) AS penguin_count
FROM penguins
WHERE body_mass_g > (
    SELECT AVG(body_mass_g) FROM penguins
    WHERE species = 'Adelie'
);

SELECT species, AVG(bill_length_mm / bill_depth_mm) AS average_ratio
FROM penguins
GROUP BY species;

SELECT species, STDDEV(body_mass_g) AS standard_deviation
FROM penguins
GROUP BY species;
